steps = [
    step("三种测试方式的上下文大小和耗时(应用只有一个 UserController 加一个 UserService,每种方式 3 次取中位数,整条命令含 JVM 与 JUnit 启动)。不启动 Spring 的 Plain 测试:中位 373 ms。@WebMvcTest(UserController.class) 加 @MockitoBean 掉 UserService:中位 1585 ms(范围 1541 到 1734),上下文里有 107 个 Bean 定义,GET /users/1 得到 mocked。@SpringBootTest 加 @AutoConfigureMockMvc:中位 1647 ms(范围 1460 到 2015),154 个 Bean 定义,GET /users/1 得到真实的 user-1。结论要克制:这个应用太小(只有 webmvc),切片和完整上下文只差 47 个 Bean 定义和几十毫秒,两者的耗时范围还有重叠;切片真正的好处在于不用把 JPA、安全、消息之类整套带进来,这个小应用没有这些东西,本篇没有测。", t=tl(S(1)), mark=lidx(S(1), 'C6_Slice1(@WebMvcTest)', 'C1_Full1(@SpringBootTest'), done=lidx(S(1), 'Plain(不启动', '[Plain]'), b=bars([['Plain 整条命令(ms)', 373, '373'], ['@WebMvcTest 整条命令(ms)', 1585, '1585'], ['@SpringBootTest 整条命令(ms)', 1647, '1647'], ['@WebMvcTest 的 Bean 定义数', 107, '107'], ['@SpringBootTest 的 Bean 定义数', 154, '154']], 1647, done=[0], mark=[1, 2], cur=[3, 4]), kv=KV([['不启动 Spring', '373 ms'], ['@WebMvcTest', '107 个 Bean 定义,1585 ms'], ['@SpringBootTest', '154 个 Bean 定义,1647 ms'], ['这个小应用', '切片与完整上下文差别不大']], ['这个小应用'])),
    step("上下文缓存。8 个测试类放在同一个 JVM 里按类名顺序跑(9 个测试方法),用 UserController 的构造器计数,每被创建一次就是新建了一个 Spring 上下文。C1_Full1 新建上下文 #1;C2_Full2 配置完全一样,没有新建(命中缓存);C3_FullMock 加了 @MockitoBean,新建 #2;C4_FullProp 加了 @TestPropertySource,新建 #3;C5_FullProfile 加了 @ActiveProfiles,新建 #4;C6_Slice1(@WebMvcTest)新建 #5,Bean 定义 107 个;C7_Slice2 与 C6 配置一样,没有新建;C9_Dirties 在类上标 @DirtiesContext(AFTER_EACH_TEST_METHOD),两个测试方法各新建一个,#6 和 #7,每个 146 个 Bean 定义。整个 JVM 里 UserController 一共被创建 7 次——8 个类、9 个方法,只创建了 7 个上下文。@MockitoBean、@TestPropertySource、@ActiveProfiles 任何一个不同,缓存就失效。", t=tl(S(2)), mark=lidx(S(2), '新建上下文 #2', '新建上下文 #3', '新建上下文 #4', '新建上下文 #6', '新建上下文 #7'), done=lidx(S(2), '>> C2_Full2', '>> C7_Slice2', '一共被创建了'), b=bars([['测试类个数', 8, '8'], ['测试方法个数', 9, '9'], ['新建的 Spring 上下文个数', 7, '7'], ['其中因为 @DirtiesContext 新建的个数', 2, '2']], 9, done=[2], mark=[3], cur=[0, 1]), kv=KV([['同样的配置', 'C1 与 C2、C6 与 C7 复用同一个上下文'], ['@MockitoBean', '换一个配置就新建上下文'], ['@TestPropertySource / @ActiveProfiles', '同样会新建'], ['@DirtiesContext', '每个方法后丢弃,下一个方法重建']], ['@MockitoBean'])),
    step("@WebMvcTest 里没有 mock 掉 UserService 会怎样。切片只加载 Web 层的 Bean(控制器、过滤器、转换器这类),@Service 不在里面:测试失败,退出码 1,tests failed 1;原因是 Failed to load ApplicationContext,最里面的异常是 UnsatisfiedDependencyException: Error creating bean with name 'userController' …… No qualifying bean of type 'demo.UserService' available。这个错误是测试的第一个真实信号,告诉你切片只加载了你想测的那一层,依赖要用 @MockitoBean 补上。", t=tl(S(3)), mark=lidx(S(3), 'No qualifying bean'), done=lidx(S(3), '退出码 1', 'Failed to load'), b=bars([['没 mock 时 tests failed 个数', 1, '1'], ['没 mock 时 tests successful 个数', 0, '0']], 1, mark=[0], done=[1]), kv=KV([['切片', '只加载 Web 层的 Bean'], ['缺少的依赖', '用 @MockitoBean 补上'], ['典型错误', 'No qualifying bean of type …'], ['外层异常', 'Failed to load ApplicationContext']], ['典型错误'])),
]
